    elif op == "get_default":
        if not isinstance(payload["m"], dict) or "key" not in payload:
            raise ValueError("bad lookup payload")
    elif op == "format_pair":
        if "a" not in payload or "b" not in payload:
            raise ValueError("bad pair payload")
    else:
        raise ValueError(op)

